import React from 'react';

/** Effect applied to streaming text. */
export type StreamingTextEffect = 'scanline' | 'wave' | 'fade';

/** Terminal-style caret shape rendered at the stream tail. */
export type StreamingTextCaret = 'block' | 'line';

/** Props for the {@link StreamingText} component. */
export interface StreamingTextProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Terminal-style blinking caret at the stream tail. `'block'` renders █,
   * `'line'` renders a thin ▏. Omit or `false` to hide. Pair with
   * `usePacedText`'s `isCatchingUp` so the caret shows only while text arrives.
   */
  caret?: StreamingTextCaret | false;
  /** @deprecated Use {@link StreamingTextProps.caret} instead. `true` ≈ `caret="block"`. */
  cursor?: boolean;
  /** Animation effect applied to the text. */
  effect?: StreamingTextEffect;
  /** Additional CSS class names. */
  className?: string;
  /** Text content to display. */
  children?: React.ReactNode;
}

/**
 * Streaming text container with a terminal-style block caret and optional
 * effects. Designed to render text whose reveal is already paced upstream
 * (e.g. via `usePacedText`) — it does not fade individual tokens, avoiding the
 * per-token opacity flicker that reads as cheap.
 *
 * Renders a `<div class="sk-streaming-text">` with `data-caret` / `data-effect`.
 */
export const StreamingText = React.forwardRef<HTMLDivElement, StreamingTextProps>(
  ({ caret, cursor, effect, className, children, ...rest }, ref) => {
    const resolvedCaret = caret === false ? undefined : caret ?? (cursor ? 'block' : undefined);
    return (
      <div
        ref={ref}
        className={`sk-streaming-text${className ? ` ${className}` : ''}`}
        data-caret={resolvedCaret}
        data-effect={effect}
        {...rest}
      >
        {children}
      </div>
    );
  },
);

StreamingText.displayName = 'StreamingText';

/**
 * skeehn — StreamingText Component
 *
 * @component sk-streaming-text
 * @effects   scanline | wave | fade | dither
 * @states    [data-cursor] | [data-loading] | [data-skeleton]
 * @features  Word-by-word dither fade-in, scanline effect, wave motion
 * @a11y      aria-live="polite" recommended, reduced motion support
 * @print     Static text, no animations
 */

.sk-streaming-text { font-family: var(--sk-font-mono); font-size: var(--sk-font-size-sm); line-height: var(--sk-line-height); white-space: pre-wrap; position: relative; }
.sk-streaming-text[data-cursor="true"]::after { content: "▋"; display: inline-block; color: hsl(var(--sk-primary)); animation: sk-ascii-blink 1s steps(2) infinite; margin-left: 0.1em; }
.sk-streaming-text[data-caret="block"]::after { content: "█"; display: inline-block; color: hsl(var(--sk-primary)); animation: sk-ascii-blink 1s steps(2) infinite; margin-left: 0.05em; }
.sk-streaming-text[data-caret="line"]::after { content: "▏"; display: inline-block; color: hsl(var(--sk-primary)); animation: sk-ascii-blink 1s steps(2) infinite; margin-left: 0.02em; }
.sk-streaming-text[data-effect="scanline"] { position: relative; }
.sk-streaming-text[data-effect="scanline"]::before { content: ""; position: absolute; left: 0; right: 0; height: 1.5em; background: linear-gradient(to bottom, transparent, hsl(var(--sk-primary) / 0.05), transparent); animation: sk-scanline 2s linear infinite; pointer-events: none; }
@keyframes sk-scanline { 0% { top: -1.5em; } 100% { top: 100%; } }
.sk-streaming-text[data-effect="wave"] span { display: inline-block; animation: sk-wave 1.5s ease-in-out infinite; }
@keyframes sk-wave { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-0.1em); } }
.sk-streaming-text[data-effect="fade"] span { display: inline-block; opacity: 0; animation: sk-fade-in 0.3s ease forwards; }
@keyframes sk-fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes sk-ascii-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }

/* ============================================================
   WORD-BY-WORD DITHER FADE-IN
   Each word dithers into existence via mask density progression
   ============================================================ */

@keyframes sk-word-dither-in {
  0%   { opacity: 0; -webkit-mask-image: var(--sk-dither-b1); mask-image: var(--sk-dither-b1); }
  30%  { opacity: 0.5; -webkit-mask-image: var(--sk-dither-b4); mask-image: var(--sk-dither-b4); }
  60%  { opacity: 0.8; -webkit-mask-image: var(--sk-dither-b8); mask-image: var(--sk-dither-b8); }
  100% { opacity: 1; -webkit-mask-image: none; mask-image: none; }
}

.sk-streaming-text[data-effect="dither"] span {
  display: inline-block;
  -webkit-mask-size: 16px 16px;
  mask-size: 16px 16px;
  -webkit-mask-repeat: repeat;
  mask-repeat: repeat;
  animation: sk-word-dither-in 0.4s steps(4) both;
}

/* Stagger delay for sequential words */
.sk-streaming-text[data-effect="dither"] span:nth-child(1)  { animation-delay: 0ms; }
.sk-streaming-text[data-effect="dither"] span:nth-child(2)  { animation-delay: 40ms; }
.sk-streaming-text[data-effect="dither"] span:nth-child(3)  { animation-delay: 80ms; }
.sk-streaming-text[data-effect="dither"] span:nth-child(4)  { animation-delay: 120ms; }
.sk-streaming-text[data-effect="dither"] span:nth-child(5)  { animation-delay: 160ms; }
.sk-streaming-text[data-effect="dither"] span:nth-child(6)  { animation-delay: 200ms; }
.sk-streaming-text[data-effect="dither"] span:nth-child(7)  { animation-delay: 240ms; }
.sk-streaming-text[data-effect="dither"] span:nth-child(8)  { animation-delay: 280ms; }
.sk-streaming-text[data-effect="dither"] span:nth-child(9)  { animation-delay: 320ms; }
.sk-streaming-text[data-effect="dither"] span:nth-child(10) { animation-delay: 360ms; }
.sk-streaming-text[data-effect="dither"] span:nth-child(n+11) { animation-delay: 400ms; }

/* ============================================================
   LOADING & SKELETON
   ============================================================ */

.sk-streaming-text[data-loading] { position: relative; }
.sk-streaming-text[data-loading]::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-pattern);
  background-repeat: repeat;
  opacity: 0.06;
  animation: sk-pulse-dither 1.5s ease-in-out infinite;
  pointer-events: none;
}

.sk-streaming-text[data-skeleton] {
  color: transparent;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%;
  animation: sk-card-shimmer 1.8s ease-in-out infinite;
  border-radius: var(--sk-radius);
  min-height: 1.5rem;
}

@media print {
  .sk-streaming-text::after { display: none; }
  .sk-streaming-text::before { display: none; }
  .sk-streaming-text[data-skeleton] { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-streaming-text[data-cursor="true"]::after,
  .sk-streaming-text[data-caret]::after { animation: none; opacity: 1; }
  .sk-streaming-text[data-effect="scanline"]::before { animation: none; display: none; }
  .sk-streaming-text[data-effect="wave"] span { animation: none; }
  .sk-streaming-text[data-effect="fade"] span { animation: none; opacity: 1; }
  .sk-streaming-text[data-effect="dither"] span { animation: none; opacity: 1; -webkit-mask-image: none; mask-image: none; }
  .sk-streaming-text[data-loading]::before { animation: none; }
  .sk-streaming-text[data-skeleton] { animation: none; background: hsl(var(--sk-muted)); }
}
